/**
 * Per-character stroke counts and the word-level "hardest character" rule.
 *
 * LAYER: data-enrichment (backfill) utility. Pure apart from the one-time load of the
 * committed lib/hanziStrokeCounts.json (generated by generate-stroke-counts.js from
 * hanzi-writer-data, so it needs no node_modules dependency at run time).
 *
 * Referenced by: scripts/backfill/chinese/backfill-max-char-stroke-count.js,
 * docs/MASTERY_REWORK.md § 6 "Ordering" (the writing bar's ease key).
 */
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

/** @type {Record<string, number> | null} */
let cache = null;

/** The char → stroke-count table, loaded once. */
export function loadStrokeCounts() {
  if (!cache) {
    cache = JSON.parse(fs.readFileSync(path.join(__dirname, 'hanziStrokeCounts.json'), 'utf8'));
  }
  return cache;
}

/**
 * Stroke count of the word's HARDEST character (MAX over its characters), or null when
 * any character is missing from the data (Latin letters as in 卡拉OK, punctuation, rare
 * variants) — a partial max would rank such a word as easier than it is. Iterates code
 * points, not UTF-16 units, so astral-plane characters count once. Must agree with
 * migration 179's SQL rule.
 *
 * @param {string} word
 * @returns {number | null}
 */
export function maxCharStrokeCount(word) {
  const counts = loadStrokeCounts();
  let max = null;
  for (const char of word) {
    const n = counts[char];
    if (n === undefined) return null;
    if (max === null || n > max) max = n;
  }
  return max;
}
